// Cost-Benefit Analysis — Inti dari Economic Feasibility
function costBenefitAnalysis(costs, benefits, years) {
  const totalCost = costs.development + costs.operational * years;
  const totalBenefit = benefits.efficiency + benefits.revenue * years;

  const netBenefit = totalBenefit - totalCost;
  const roi = ((netBenefit / totalCost) * 100).toFixed(2);
  const breakEvenYear = (costs.development / (benefits.revenue - costs.operational)).toFixed(1);

  return {
    totalCost: `Rp ${totalCost.toLocaleString('id-ID')}`,
    totalBenefit: `Rp ${totalBenefit.toLocaleString('id-ID')}`,
    netBenefit: `Rp ${netBenefit.toLocaleString('id-ID')}`,
    roi: `${roi}%`,
    breakEvenYear: `${breakEvenYear} tahun`,
    rekomendasi: netBenefit > 0 ? '✅ LANJUTKAN PROYEK' : '❌ TINJAU ULANG'
  };
}

// Contoh penggunaan:
const hasil = costBenefitAnalysis(
  { development: 500_000_000, operational: 50_000_000 },
  { efficiency: 100_000_000, revenue: 200_000_000 },
  3 // tahun
);
console.log(hasil);
